-- ZIP code center points for ZIP search
-- Uses the Census 2024 Gazetteer ZCTA file, same source as the city_counties centers
-- NJ ZCTAs only (07xxx and 08xxx)
CREATE TABLE zip_codes (
  zip TEXT PRIMARY KEY CHECK (zip ~ '^[0-9]{5}$'),
  latitude DOUBLE PRECISION NOT NULL,
  longitude DOUBLE PRECISION NOT NULL
);

